# The expected pattern is for U-structures "3 X 3" to create horizontal and vertical beams
# Let me implement this

def process_u_structures(grid):
    """Apply U-structure flood logic"""
    rows = len(grid)
    cols = len(grid[0])
    out = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # Find all U-structures "3 X 3" where X != 3
    us = []
    for r in range(rows):
        for c in range(cols - 2):
            if grid[r][c] == 3 and grid[r][c+1] != 3 and grid[r][c+2] == 3:
                x = grid[r][c+1]
                if x != 3:  # Skip "3 3 3"
                    us.append((r, c+1, x))  # (row, center_col, value)

    print(f"Found {len(us)} U-structures: {us}")

    # Apply vertical beams first
    for r, c, val in us:
        for rr in range(rows):
            if out[rr][c] == 0:
                out[rr][c] = val

    # Apply horizontal beams second
    for r, c, val in us:
        for cc in range(cols):
            if out[r][cc] == 0:
                out[r][cc] = val

    return out

