    # Apply horizontal beams
    for r, c, val in us:
        for cc in range(cols):
            if result[r][cc] == 0:
                result[r][cc] = val

    return result

def apply_transform_v3(grid):
    """Vertical beams fill ALL cells (even non-zero), horizontal fills ALL (even non-zero)"""
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]

