    for r in range(rows):
        for c in range(cols - 2):
            if grid[r][c] == 3 and grid[r][c+1] != 3 and grid[r][c+2] == 3:
                x = grid[r][c+1]
                if x != 0 and x != 3:
                    us.append((r, c+1, x))

    # Add 3-barriers from original
    barriers = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3:
                barriers.append((r, c))

    # Fill entire grid with beams
